package ledger

import "errors"

var ErrOverdraft = errors.New("ledger: overdraft")

type Entry struct {
	Account string
	Cents   int64
}

type Ledger struct {
	balances map[string]int64
	limit    int64
}

func New(limit int64) *Ledger { return &Ledger{balances: map[string]int64{}, limit: limit} }

// Post applies an entry. A debit may take an account down to -limit, no further.
func (l *Ledger) Post(e Entry) error {
	next := l.balances[e.Account] + e.Cents
	if next < l.limit {
		return ErrOverdraft
	}
	l.balances[e.Account] = next
	return nil
}

func (l *Ledger) Balance(account string) int64 { return l.balances[account] }

// Transfer moves cents between two accounts, all or nothing.
func (l *Ledger) Transfer(from, to string, cents int64) error {
	if err := l.Post(Entry{from, -cents}); err != nil {
		return err
	}
	return l.Post(Entry{to, cents})
}

