package ledger

import "testing"

func TestPostWithinLimit(t *testing.T) {
	l := New(500)
	if err := l.Post(Entry{"a", -400}); err != nil {
		t.Fatalf("debit within limit: %v", err)
	}
}

func TestPostOverdraft(t *testing.T) {
	l := New(500)
	if err := l.Post(Entry{"a", -600}); err != ErrOverdraft {
		t.Fatalf("want ErrOverdraft, got %v", err)
	}
}

func TestTransfer(t *testing.T) {
	l := New(0)
	_ = l.Post(Entry{"a", 1000})
	if err := l.Transfer("a", "b", 300); err != nil {
		t.Fatal(err)
	}
	if l.Balance("a") != 700 || l.Balance("b") != 300 {
		t.Fatalf("balances a=%d b=%d", l.Balance("a"), l.Balance("b"))
	}
}

package report

import (
	"fmt"
	"sort"
	"strings"
)

// Summary renders balances sorted by account, one per line, in dollars.
func Summary(balances map[string]int64) string {
	keys := make([]string, 0, len(balances))
	for k := range balances {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		fmt.Fprintf(&b, "%s %d.%02d\n", k, balances[k]/100, balances[k]%100)
	}
	return b.String()
}

